                  <p className="text-sm font-bold text-green-600 italic leading-relaxed">
                    名称 / 宣传图 / 标签分类 / 详细介绍
                  </p>
                </div>
              </div>
              <div className="flex items-start gap-6 p-8 bg-zinc-50 border border-dashed border-zinc-200 rounded-[2rem]">
