                  <p className="text-sm font-bold text-zinc-400 italic leading-relaxed">
                    服务器 IP 地址 / 客户端版本号
                  </p>
                </div>
              </div>
            </div>
          )}
        </header>

        <form onSubmit={handleSubmit(onSubmit)} className="space-y-20">
          {/* Cover Upload */}
          <section id="cover" ref={sectionRefs.cover} className="scroll-mt-24">
            <Controller 
              name="image"
              control={control}
              render={({ field }) => (
                <MatrixImageUpload 
