                    <label className="text-[10px] font-black font-mono uppercase tracking-[0.4em] text-zinc-300 italic flex items-center gap-3">
                       <GeometricLantern variant="network" className="w-3.5 h-3.5" /> {t('editor.field.ip.label')}
