                    </button>
                  </div>
                  <div className="relative group/field">
                    <input 
                      {...register('ip')}
                      disabled={!!serverId}
                      className={`matrix-input ${serverId ? 'opacity-50 cursor-not-allowed bg-zinc-50' : ''}`}
                      placeholder={t('editor.field.ip.placeholder')}
                    />
                    {serverId && (
