type ApiResponse<T = any> = {
  status: number;
  ok: boolean;
  data: T | null;
  text: string;
  headers: Headers;
};

type SessionState = {
  cookie: string;
};

const BASE_URL = (process.env.SMOKE_WEB_BASE_URL || 'https://mc-u.top').replace(/\/+$/, '');
