async function waitPublicCleared(marker: string, maxAttempts = 8, intervalMs = 1500) {
  let lastResponse: ApiResponse<any> | null = null;
  let lastCount = -1;
  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
    const resp = await requestJson(`/api/v1/public/servers?page=1&limit=20&search=${encodeURIComponent(marker)}`);
    lastResponse = resp;
    const items = normalizeListData(resp.data);
    lastCount = items.length;
    if (resp.ok && items.length === 0) {
      return { cleared: true, attempts: attempt, response: resp, count: 0 };
    }
    if (attempt < maxAttempts) {
      await sleep(intervalMs);
    }
  }
  return {
    cleared: false,
    attempts: maxAttempts,
    response: lastResponse,
    count: lastCount,
  };
}

async function loginWithSession(session: SessionState, identifier: string, password: string) {
  const login = await requestJson('/api/v1/auth/login', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ identifier, password }),
  }, session);
  if (!login.ok) {
    throw new Error(`Login failed for ${identifier}: ${safeMsg(login)}`);
  }
  const token = login.data?.data?.token || '';
  if (!token) {
    throw new Error(`Login token missing for ${identifier}`);
  }
  const csrf = await requestJson('/api/v1/csrf-token', {}, session);
  if (!csrf.ok) {
    throw new Error(`CSRF token request failed for ${identifier}: ${safeMsg(csrf)}`);
  }
  const csrfToken = csrf.data?.data?.csrfToken || csrf.data?.csrfToken || '';
  if (!csrfToken) {
    throw new Error(`CSRF token missing for ${identifier}`);
  }
  return { token, csrfToken, login, csrf };
}

async function main() {
  const checks: Check[] = [];
  const adminSession: SessionState = { cookie: '' };
  const userSession: SessionState = { cookie: '' };
  const marker = `wallet-listing-${Date.now()}-${crypto.randomBytes(3).toString('hex')}`;

  let createdServerId: number | null = null;

  const adminAuth = await loginWithSession(adminSession, ADMIN_IDENTIFIER, ADMIN_PASSWORD);
  const listingUser = LISTING_USER_EMAIL && LISTING_USER_PASSWORD
    ? { email: LISTING_USER_EMAIL, password: LISTING_USER_PASSWORD }
    : await createVerifiedListingUser(adminSession, adminAuth);
  const userAuth = await loginWithSession(userSession, listingUser.email, listingUser.password);

  add(checks, 'admin-login', 'PASS', `admin=${ADMIN_IDENTIFIER}`, adminAuth.login.status);
  add(checks, 'user-login', 'PASS', `user=${listingUser.email}`, userAuth.login.status);

  const adminHeaders = {
    Authorization: `Bearer ${adminAuth.token}`,
    'Content-Type': 'application/json',
    'x-csrf-token': adminAuth.csrfToken,
  };
  const userHeaders = {
    Authorization: `Bearer ${userAuth.token}`,
    'Content-Type': 'application/json',
    'x-csrf-token': userAuth.csrfToken,
  };
  const userReadHeaders = {
    Authorization: `Bearer ${userAuth.token}`,
  };

  const quotaBefore = await requestJson('/api/v1/servers/me', {
    headers: userReadHeaders,
  }, userSession);
  const canPublish = quotaBefore.data?.data?.can_publish === true;
  const maxCards = Number(quotaBefore.data?.data?.max_cards ?? 0);
  add(
    checks,
    'user-quota',
    quotaBefore.ok && canPublish && maxCards >= 1 ? 'PASS' : 'FAIL',
    quotaBefore.ok
      ? `can_publish=${String(canPublish)} max_cards=${String(maxCards)}`
      : safeMsg(quotaBefore),
    quotaBefore.status,
  );

  const walletBeforeResp = await requestJson('/api/v1/wallet', {
    headers: userReadHeaders,
  }, userSession);
  const walletBefore = Number(walletBeforeResp.data?.data?.balance ?? NaN);
  add(
    checks,
    'wallet-before',
    walletBeforeResp.ok && Number.isFinite(walletBefore) ? 'PASS' : 'FAIL',
    walletBeforeResp.ok ? `balance=${walletBefore}` : safeMsg(walletBeforeResp),
    walletBeforeResp.status,
  );

  const createRecharge = await requestJson('/api/v1/payment/create', {
    method: 'POST',
    headers: userHeaders,
    body: JSON.stringify({
      planId: 'custom',
      amount: RECHARGE_AMOUNT,
      paymentMethod: 'alipay',
    }),
  }, userSession);
  const rechargeOrderId = createRecharge.data?.data?.orderId || createRecharge.data?.data?.paymentId;
  add(
    checks,
    'create-recharge',
    createRecharge.ok && typeof rechargeOrderId === 'string' ? 'PASS' : 'FAIL',
    createRecharge.ok ? `orderId=${String(rechargeOrderId)}` : safeMsg(createRecharge),
    createRecharge.status,
  );

  const completeRecharge = await requestJson('/api/v1/payment/admin/complete-order', {
    method: 'POST',
    headers: adminHeaders,
    body: JSON.stringify({ orderId: rechargeOrderId }),
  }, adminSession);
  add(
    checks,
    'complete-recharge',
    completeRecharge.ok ? 'PASS' : 'FAIL',
    completeRecharge.ok ? 'admin completed recharge order' : safeMsg(completeRecharge),
    completeRecharge.status,
  );

  const walletAfterRechargeResp = await requestJson('/api/v1/wallet', {
    headers: userReadHeaders,
  }, userSession);
  const walletAfterRecharge = Number(walletAfterRechargeResp.data?.data?.balance ?? NaN);
  const rechargeDelta = roundCurrency(walletAfterRecharge - walletBefore);
  add(
    checks,
    'wallet-after-recharge',
    walletAfterRechargeResp.ok && rechargeDelta === roundCurrency(RECHARGE_AMOUNT) ? 'PASS' : 'FAIL',
    walletAfterRechargeResp.ok
      ? `balance=${walletAfterRecharge} delta=${rechargeDelta}`
      : safeMsg(walletAfterRechargeResp),
    walletAfterRechargeResp.status,
  );

  const createServer = await requestJson('/api/v1/servers', {
    method: 'POST',
    headers: userHeaders,
    body: JSON.stringify({
      name: `Smoke Listing ${marker}`,
      summary: 'wallet charged smoke listing',
      content_html: `This is an automated smoke listing payload for ${marker}.`,
      ip: `${marker}.example.com`,
      tags: JSON.stringify(['smoke', 'wallet', 'listing']),
      thumbnail: THUMBNAIL_PATH,
      supported_versions: JSON.stringify(['1.20.1']),
      listing_plan: LISTING_PLAN,
    }),
  }, userSession);
  createdServerId = Number(createServer.data?.data?.id || 0) || null;
  const expectedPrice = PLAN_PRICE_MAP[LISTING_PLAN];
  const listingPricePaid = Number(createServer.data?.data?.listing_price_paid ?? NaN);
  add(
    checks,
    'create-server',
    createServer.ok && createdServerId !== null && listingPricePaid === expectedPrice * 100 ? 'PASS' : 'FAIL',
    createServer.ok
      ? `serverId=${String(createdServerId)} listing_price_paid=${String(listingPricePaid)}`
      : safeMsg(createServer),
    createServer.status,
  );

  const walletAfterPublishResp = await requestJson('/api/v1/wallet', {
    headers: userReadHeaders,
  }, userSession);
  const walletAfterPublish = Number(walletAfterPublishResp.data?.data?.balance ?? NaN);
  const publishDelta = roundCurrency(walletAfterRecharge - walletAfterPublish);
  add(
    checks,
    'wallet-after-publish',
    walletAfterPublishResp.ok && publishDelta === expectedPrice ? 'PASS' : 'FAIL',
    walletAfterPublishResp.ok
      ? `balance=${walletAfterPublish} publish_delta=${publishDelta}`
      : safeMsg(walletAfterPublishResp),
    walletAfterPublishResp.status,
  );

  const approveServer = await requestJson(`/api/v1/review/${createdServerId}`, {
    method: 'POST',
    headers: adminHeaders,
    body: JSON.stringify({
      status: 'APPROVED',
      notes: `smoke approved ${marker}`,
    }),
  }, adminSession);
  add(
    checks,
    'approve-server',
    approveServer.ok && approveServer.data?.data?.review_status === 'APPROVED' ? 'PASS' : 'FAIL',
    approveServer.ok
      ? `review_status=${String(approveServer.data?.data?.review_status)}`
      : safeMsg(approveServer),
    approveServer.status,
  );

  const publicList = await requestJson(`/api/v1/public/servers?page=1&limit=20&search=${encodeURIComponent(marker)}`);
  const publicItems = normalizeListData(publicList.data);
  const publicMatch = publicItems.find((item) => item?.id === createdServerId);
  add(
    checks,
    'public-visible',
    publicList.ok && Boolean(publicMatch) ? 'PASS' : 'FAIL',
    publicList.ok ? `public_matches=${String(publicItems.length)}` : safeMsg(publicList),
    publicList.status,
  );

  const deleteServer = await requestJson(`/api/v1/servers/${createdServerId}`, {
    method: 'DELETE',
    headers: {
      Authorization: `Bearer ${adminAuth.token}`,
      'x-csrf-token': adminAuth.csrfToken,
    },
  }, adminSession);
  add(
    checks,
    'delete-server',
    deleteServer.ok ? 'PASS' : 'FAIL',
    deleteServer.ok ? 'test listing deleted' : safeMsg(deleteServer),
    deleteServer.status,
  );

  const ownedAfterDelete = await requestJson(`/api/v1/servers?page=1&limit=20&search=${encodeURIComponent(marker)}`, {
    headers: userReadHeaders,
  }, userSession);
  const ownedAfterDeleteItems = normalizeListData(ownedAfterDelete.data);
  const ownedCleared = ownedAfterDelete.ok && ownedAfterDeleteItems.length === 0;
  add(
    checks,
    'owned-cleared',
    ownedCleared ? 'PASS' : 'FAIL',
    ownedAfterDelete.ok ? `owned_matches=${String(ownedAfterDeleteItems.length)}` : safeMsg(ownedAfterDelete),
    ownedAfterDelete.status,
  );

  const publicAfterDelete = await waitPublicCleared(marker);
  const publicClearedStatus: Status = publicAfterDelete.cleared
    ? 'PASS'
    : deleteServer.ok && ownedCleared
      ? 'WARN'
      : 'FAIL';
  add(
    checks,
    'public-cleared',
    publicClearedStatus,
    publicAfterDelete.response?.ok
      ? `${publicClearedStatus === 'WARN' ? 'eventual-sync-pending' : 'public_matches'}=${String(publicAfterDelete.count)} attempts=${String(publicAfterDelete.attempts)}`
      : safeMsg(publicAfterDelete.response || { status: 0, ok: false, data: null, text: 'no response', headers: new Headers() }),
    publicAfterDelete.response?.status,
  );

  const failed = checks.filter((item) => item.status === 'FAIL');
  const report = {
    timestamp: new Date().toISOString(),
    baseUrl: BASE_URL,
    listingPlan: LISTING_PLAN,
    rechargeAmount: RECHARGE_AMOUNT,
    marker,
    createdServerId,
    checks,
    failedCount: failed.length,
  };

  const fullReportPath = resolve(process.cwd(), REPORT_PATH);
  mkdirSync(dirname(fullReportPath), { recursive: true });
  writeFileSync(fullReportPath, `${JSON.stringify(report, null, 2)}\n`, 'utf8');

  console.log(`[smoke:wallet-listing] Base URL: ${BASE_URL}`);
  for (const check of checks) {
    console.log(`- ${check.status} ${check.name}: ${check.detail}`);
  }
  console.log(`[smoke:wallet-listing] Report written to: ${fullReportPath}`);

  if (failed.length > 0) {
    process.exit(1);
  }
}

main().catch((error) => {
  console.error('[smoke:wallet-listing] Unexpected error:', error);
  process.exit(1);
});

import { Request, Response, NextFunction } from 'express';

import crypto from 'crypto';

import Session from 'supertokens-node/recipe/session';

import jwt from 'jsonwebtoken';

import prisma, { User } from '../db';

import { sendSuccess, toSafeUser } from '../utils/response';

import { AppError, ErrorCode } from '../utils/errors';

import { logger } from '../utils/logger';

import { redisService } from '../services/redisService';

import { sendEmailLoginCode } from '../services/emailService';

import { sendPhoneLoginCode } from '../services/smsService';

import { getOrCreateSuperTokensUser } from '../services/superTokensUser';
import { getJwtSecret } from '../utils/securityConfig';



const CODE_TTL_MINUTES = 10;

const CODE_RATE_LIMIT_MINUTES = 1;

const MAX_VERIFY_ATTEMPTS = 5;

const LOCKOUT_DURATION_MS = 15 * 60 * 1000; // 15 分钟冷却期

const CODE_SEND_INTERVAL_MS = 60 * 1000; // 60 秒内不可重复发送



const USER_CACHE_PREFIX = 'user:cache:';

const USER_CACHE_TTL = 30;



function normalizeEmail(email: string) {

  return email.trim().toLowerCase();

}



function normalizePhone(phone: string) {

  return phone.trim().replace(/[\s-]/g, '');

}



function isPhone(value: string): boolean {

  return /^(\+?\d{1,3}[- ]?)?\d{7,15}$/.test(value.replace(/[\s-]/g, ''));

}


function isEmail(value: string): boolean {

  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim());

}


function maskIdentifier(value: string, type: 'email' | 'phone'): string {

  if (type === 'email') {

    const [name = '', domain = ''] = value.split('@');

    const maskedName = name.length <= 2 ? `${name[0] || '*'}***` : `${name.slice(0, 2)}***`;

    return domain ? `${maskedName}@${domain}` : maskedName;

  }

  const normalized = normalizePhone(value);

  if (normalized.length <= 4) return '****';

  return `${normalized.slice(0, 3)}****${normalized.slice(-2)}`;

}



function generateCode() {

  return String(Math.floor(100000 + Math.random() * 900000));

}



function generateCodeHash(identifier: string, code: string) {

  const secret = getJwtSecret();

  return crypto.createHmac('sha256', secret).update(`${identifier}:${code}`).digest('hex');

}



/**
 * 统一标识符解析器
 * 从请求体中提取 email 或 phone，返回 { identifier, type, address }
 */

function parseIdentifier(body: Record<string, unknown>) {

  const email = typeof body?.email === 'string' ? body.email.trim() : '';

  const phone = typeof body?.phone === 'string' ? body.phone.trim() : '';



  if (email) {

    if (!isEmail(email)) {

      throw new AppError('Invalid email format', 400, ErrorCode.VALIDATION_ERROR);

    }

    return { identifier: normalizeEmail(email), type: 'email' as const, address: normalizeEmail(email) };

  }

  if (phone) {

    if (!isPhone(phone)) {

      throw new AppError('Invalid phone format', 400, ErrorCode.VALIDATION_ERROR);

    }

    return { identifier: normalizePhone(phone), type: 'phone' as const, address: normalizePhone(phone) };

  }



  throw new AppError('Email or phone is required', 400, ErrorCode.VALIDATION_ERROR);

}



/**
 * 根据标识符类型查询用户
 */

async function findUserByIdentifier(identifier: string) {

  return prisma.user.findFirst({

    where: {

      OR: [

        { email: identifier },

        { phone: identifier },

      ],

    },

  });

}



/**
 * 发送验证码
 * 支持 email 和 phone 双通道
 */

export const sendLoginCode = async (req: Request, res: Response, next: NextFunction) => {

  try {

    const { identifier, type, address } = parseIdentifier(req.body);

    logger.debug(`[AuthCode] sendLoginCode: identifier=${maskIdentifier(address, type)} type=${type}`);



    const user = await findUserByIdentifier(identifier);

    if (!user) {

      return sendSuccess(res, { [type]: maskIdentifier(address, type) }, 'If the account exists, a verification code has been sent');

    }



    // 检查发送频率限制

    const now = Date.now();

    const lastSendAt = user.last_code_send_at ? new Date(user.last_code_send_at).getTime() : 0;

    if (lastSendAt > 0 && now - lastSendAt < CODE_SEND_INTERVAL_MS) {

      throw new AppError('Please wait before requesting a new code', 429, ErrorCode.RATE_LIMITED);

    }



    // 检查是否被锁定

    if (user.login_count && user.login_count >= MAX_VERIFY_ATTEMPTS) {

      if (user.login_lockout_at) {

        const lockoutExpiry = new Date(user.login_lockout_at).getTime() + LOCKOUT_DURATION_MS;

        if (now < lockoutExpiry) {

          throw new AppError('Too many failed attempts. Please try again later.', 429, ErrorCode.RATE_LIMITED);

        } else {

          await prisma.user.update({

            where: { id: user.id },

            data: { login_count: 0, login_lockout_at: null },

          });

        }

      }

    }



    const code = generateCode();

    const hashedCode = generateCodeHash(address, code);



    await prisma.user.update({

      where: { id: user.id },

      data: {

        verification_token: hashedCode,

        token_expiry: new Date(Date.now() + CODE_TTL_MINUTES * 60 * 1000),

        last_code_send_at: new Date(),

      },

    });



    // 根据类型选择发送渠道

    if (type === 'phone') {

      await sendPhoneLoginCode(address, code);

    } else {

      await sendEmailLoginCode(address, code);

    }



    return sendSuccess(res, { [type]: maskIdentifier(address, type) }, 'If the account exists, a verification code has been sent');

  } catch (error) {

    logger.error('[AuthCode] Failed to send login code:', error);

    next(error);

  }

};



/**

 * 验证验证码

 * 支持 email 和 phone 双通道

 */

export const verifyLoginCode = async (req: Request, res: Response, next: NextFunction) => {

  try {

    const { identifier, type, address } = parseIdentifier(req.body);

    const code = typeof req.body?.code === 'string' ? req.body.code.trim() : '';

    if (!code) {

      throw new AppError('Code is required', 400, ErrorCode.VALIDATION_ERROR);

    }



    logger.debug(`[AuthCode] verifyLoginCode: identifier=${maskIdentifier(address, type)} type=${type}`);



    const user = await findUserByIdentifier(identifier);

    if (!user) {

      throw new AppError('Invalid code', 400, ErrorCode.BAD_REQUEST);

    }



    // 检查是否被锁定

    if (user.login_count && user.login_count >= MAX_VERIFY_ATTEMPTS) {

      if (user.login_lockout_at) {

        const now = Date.now();

        const lockoutExpiry = new Date(user.login_lockout_at).getTime() + LOCKOUT_DURATION_MS;

        if (now < lockoutExpiry) {

          throw new AppError('Too many failed attempts. Please try again later.', 429, ErrorCode.RATE_LIMITED);

        } else {

          await prisma.user.update({

            where: { id: user.id },

            data: { login_count: 0, login_lockout_at: null },

          });

        }

      }

    }



    if (!user.verification_token || !user.token_expiry || user.token_expiry < new Date()) {

      throw new AppError('Code expired', 400, ErrorCode.BAD_REQUEST);

    }



    if (user.verification_token !== generateCodeHash(address, code)) {

      const nextCount = (user.login_count || 0) + 1;

      const updateData: Record<string, unknown> = { login_count: nextCount };

      if (nextCount >= MAX_VERIFY_ATTEMPTS) {

        updateData.login_lockout_at = new Date();

      }

      await prisma.user.update({ where: { id: user.id }, data: updateData });

      throw new AppError('Invalid code', 400, ErrorCode.BAD_REQUEST);

    }



    // 验证成功：更新用户状态

    const updatedUser = await prisma.user.update({

      where: { id: user.id },

      data: {

        email_verified: true,

        verification_token: null,

        token_expiry: null,

        login_count: 0,

        login_lockout_at: null,

        last_login_at: new Date(),

      },

    });



    // 获取 identifier 对应的邮箱（SuperTokens 需要 email）

    const userEmail = user.email || user.phone;



    // 创建 SuperTokens 会话

    let stUserId = user.supertokens_user_id;

    if (!stUserId) {

      stUserId = await getOrCreateSuperTokensUser(userEmail!);

      if (stUserId) {

        await prisma.user.update({

          where: { id: user.id },

          data: { supertokens_user_id: stUserId },

        });

      }

    }



    if (stUserId) {

      try {

        await Session.createNewSession(req, res, process.env.NEXT_PUBLIC_SUPER_TOKENS_TENANT_ID || '1', stUserId as any);

        await redisService.del(`${USER_CACHE_PREFIX}${user.id}`);

      } catch (stError) {

        logger.warn('[AuthCode] Failed to create SuperTokens session after code verification:', stError);

      }

    }



    const token = jwt.sign(
      { userId: user.id, mode: 'local-auth' },
      getJwtSecret(),
      { expiresIn: '7d' },
    );

    return sendSuccess(res, {
      [type]: address,
      token,
      user: toSafeUser({ ...updatedUser, supertokens_user_id: stUserId || updatedUser.supertokens_user_id }, { mask: false }),
      mode: 'code-auth',
    }, 'Code verified and logged in', 200, undefined, { mask: false });

  } catch (error) {

    next(error);

  }

};

import type { Request, Response as ExpressResponse, NextFunction } from 'express';
import crypto from 'crypto';
import jwt from 'jsonwebtoken';
import prisma from '../db';
import { AppError, ErrorCode } from '../utils/errors';
import { logger } from '../utils/logger';
import { toSafeUser } from '../utils/response';
import { getJwtSecret, isTrustedHost } from '../utils/securityConfig';

const GITHUB_STATE_COOKIE = 'github_oauth_state';

function githubConfigured() {
  return Boolean(process.env.GITHUB_CLIENT_ID?.trim() && process.env.GITHUB_CLIENT_SECRET?.trim());
}

function frontendBaseUrl() {
  return (process.env.FRONTEND_URL || process.env.API_PUBLIC_URL || 'http://localhost:5173').replace(/\/$/, '');
}

function githubCallbackUrl(req?: Request) {
  const override = process.env.GITHUB_CALLBACK_URL?.trim();
  if (override) return override;
  if (req) {
    const host = req.get('host');
    const protocol = (req.headers['x-forwarded-proto'] as string | undefined)?.split(',')[0]?.trim() || req.protocol || 'http';
    if (host) {
      return `${protocol}://${host}${req.path}`;
    }
  }
  return '';
}

function githubCallbackUrlOverride() {
  return process.env.GITHUB_CALLBACK_URL?.trim() || '';
}

function oauthCookieOptions() {
  const isSecure = process.env.FORCE_HTTPS === 'true';
  return {
    httpOnly: true,
    secure: isSecure,
    sameSite: 'lax' as const,
    path: '/',
    maxAge: 10 * 60 * 1000,
    domain: process.env.COOKIE_DOMAIN || undefined,
  };
}

const OAUTH_FETCH_TIMEOUT_MS = Number(process.env.OAUTH_HTTP_TIMEOUT_MS || 15000);
const OAUTH_FETCH_RETRY_TIMES = Number(process.env.OAUTH_HTTP_RETRIES || 2);

function isRetryableOAuthError(error: unknown): boolean {
  if (!(error instanceof Error)) return false;
  const message = error.message.toLowerCase();
  return (
    error.name === 'TimeoutError' ||
    error.name === 'AbortError' ||
    message.includes('timed out') ||
    message.includes('timeout') ||
    message.includes('ecconnreset') ||
    message.includes('econnreset') ||
    message.includes('econnrefused') ||
    message.includes('socket hang up') ||
    message.includes('network')
  );
}

async function fetchWithRetry(
  url: string,
  init: RequestInit,
  options: { retries?: number; timeoutMs?: number } = {},
): Promise<globalThis.Response> {
  const retries = options.retries ?? OAUTH_FETCH_RETRY_TIMES;
  const timeoutMs = options.timeoutMs ?? OAUTH_FETCH_TIMEOUT_MS;
  let lastError: unknown = null;

  for (let attempt = 0; attempt <= retries; attempt += 1) {
    try {
      return await fetch(url, {
        ...init,
        signal: AbortSignal.timeout(timeoutMs),
      });
    } catch (error) {
      lastError = error;
      const shouldRetry = attempt < retries && isRetryableOAuthError(error);
      if (!shouldRetry) {
        throw error;
      }
      const delayMs = 250 * (attempt + 1);
      await new Promise((resolve) => setTimeout(resolve, delayMs));
      logger.warn('[GitHubOAuth] transient request error, retrying', {
        url,
        attempt: attempt + 1,
        retries,
        delayMs,
        error: error instanceof Error ? error.message : String(error),
      });
    }
  }

  throw lastError instanceof Error ? lastError : new Error('OAuth request failed');
}

async function resolveUniqueUsername(baseLogin: string | undefined) {
  const root = String(baseLogin || 'github').trim().replace(/[^a-zA-Z0-9_-]/g, '_').slice(0, 24) || 'github';
  for (let index = 0; index < 20; index += 1) {
    const candidate = index === 0 ? root : `${root}_${index}`;
    const existing = await prisma.user.findFirst({ where: { username: candidate }, select: { id: true } });
    if (!existing) return candidate;
  }
  return `${root}_${crypto.randomUUID().slice(0, 8)}`;
}

async function exchangeGitHubCode(code: string, callbackUrl?: string) {
  const params = new URLSearchParams({
    client_id: process.env.GITHUB_CLIENT_ID!,
    client_secret: process.env.GITHUB_CLIENT_SECRET!,
    code,
  });
  if (callbackUrl) {
    params.set('redirect_uri', callbackUrl);
  }

  let response: globalThis.Response;
  try {
    response = await fetchWithRetry(
      'https://github.com/login/oauth/access_token',
      {
        method: 'POST',
        headers: {
          Accept: 'application/json',
          'Content-Type': 'application/x-www-form-urlencoded',
          'User-Agent': 'QianFu-GitHub-OAuth',
        },
        body: params,
      },
      {
        retries: OAUTH_FETCH_RETRY_TIMES,
        timeoutMs: OAUTH_FETCH_TIMEOUT_MS,
      },
    );
  } catch (error) {
    throw new AppError(
      'GitHub token exchange timed out, please try again',
      504,
      ErrorCode.AUTHENTICATION_FAILED,
    );
  }

  const payload = await response.json().catch(() => null) as
    | { access_token?: string; error?: string; error_description?: string }
    | null;

  if (!response.ok || !payload?.access_token) {
    throw new AppError(
      payload?.error_description || payload?.error || `GitHub token exchange failed (${response.status})`,
      502,
      ErrorCode.AUTHENTICATION_FAILED,
    );
  }

  return payload.access_token;
}

async function fetchGitHubProfile(accessToken: string) {
  const commonHeaders = {
    Authorization: `Bearer ${accessToken}`,
    Accept: 'application/vnd.github+json',
    'User-Agent': 'QianFu-GitHub-OAuth',
  };

  let profileResponse: globalThis.Response;
  let emailsResponse: globalThis.Response;
  try {
    [profileResponse, emailsResponse] = await Promise.all([
      fetchWithRetry(
        'https://api.github.com/user',
        { headers: commonHeaders },
        { retries: OAUTH_FETCH_RETRY_TIMES, timeoutMs: OAUTH_FETCH_TIMEOUT_MS },
      ),
      fetchWithRetry(
        'https://api.github.com/user/emails',
        { headers: commonHeaders },
        { retries: OAUTH_FETCH_RETRY_TIMES, timeoutMs: OAUTH_FETCH_TIMEOUT_MS },
      ),
    ]);
  } catch {
    throw new AppError('GitHub profile request timed out, please try again', 504, ErrorCode.AUTHENTICATION_FAILED);
  }

  const profile = await profileResponse.json().catch(() => null) as
    | { id?: number; login?: string; name?: string; avatar_url?: string; email?: string | null }
    | null;
  const emails = await emailsResponse.json().catch(() => []) as Array<{
    email?: string;
    primary?: boolean;
    verified?: boolean;
  }>;

  if (!profileResponse.ok || !profile?.id) {
    throw new AppError('Failed to fetch GitHub profile', 502, ErrorCode.AUTHENTICATION_FAILED);
  }

  const verifiedPrimary =
    emails.find((item) => item.verified && item.primary)?.email ||
    emails.find((item) => item.verified)?.email ||
    profile.email ||
    '';

  if (!verifiedPrimary) {
    throw new AppError('GitHub account did not provide a verified email', 400, ErrorCode.VALIDATION_ERROR);
  }

  return {
    githubId: String(profile.id),
    email: verifiedPrimary.toLowerCase(),
    username: profile.login || undefined,
    displayName: profile.name || profile.login || undefined,
    avatarUrl: profile.avatar_url || undefined,
  };
}

async function upsertUserFromGitHubProfile(profile: {
  githubId: string;
  email: string;
  username?: string;
  displayName?: string;
  avatarUrl?: string;
}) {
  const existingByEmail = await prisma.user.findFirst({
    where: { email: profile.email },
  });

  if (existingByEmail) {
    return prisma.user.update({
      where: { id: existingByEmail.id },
      data: {
        email_verified: true,
        avatar_url: existingByEmail.avatar_url || profile.avatarUrl,
        display_name: existingByEmail.display_name || profile.displayName,
        username: existingByEmail.username || (await resolveUniqueUsername(profile.username)),
        last_login_at: new Date(),
        login_count: { increment: 1 },
      },
    });
  }

  return prisma.user.create({
    data: {
      email: profile.email,
      email_verified: true,
      username: await resolveUniqueUsername(profile.username),
      display_name: profile.displayName,
      avatar_url: profile.avatarUrl,
      role: 'NORMAL',
      last_login_at: new Date(),
      login_count: 1,
    },
  });
}

function buildFrontendCallbackUrl(params: Record<string, string>) {
  const base = frontendBaseUrl();
  const query = new URLSearchParams(params).toString();
  const hash = `/oauth/callback/github${query ? `?${query}` : ''}`;
  try {
    const callback = new URL(base);
    if (process.env.NODE_ENV === 'production' && !isTrustedHost(callback.host)) {
      logger.error('[GitHubOAuth] Untrusted frontend callback host, using same-origin fallback', {
        host: callback.host,
      });
      return `/#${hash}`;
    }
    callback.hash = hash;
    return callback.toString();
  } catch {
    return `/#${hash}`;
  }
}

export const startGitHubAuth = async (_req: Request, res: ExpressResponse, next: NextFunction) => {
  try {
    if (!githubConfigured()) {
      throw new AppError('GitHub OAuth is not configured', 503, ErrorCode.SERVICE_UNAVAILABLE);
    }

    const state = crypto.randomUUID();
    res.cookie(GITHUB_STATE_COOKIE, state, oauthCookieOptions());

    const authorizeUrl = new URL('https://github.com/login/oauth/authorize');
    authorizeUrl.searchParams.set('client_id', process.env.GITHUB_CLIENT_ID!);
    authorizeUrl.searchParams.set('scope', 'read:user user:email');
    authorizeUrl.searchParams.set('state', state);

    const callbackUrl = githubCallbackUrlOverride();
    if (callbackUrl) {
      authorizeUrl.searchParams.set('redirect_uri', callbackUrl);
    }

    return res.redirect(authorizeUrl.toString());
  } catch (error) {
    return next(error);
  }
};

export const handleGitHubAuthCallback = async (req: Request, res: ExpressResponse, next: NextFunction) => {
  try {
    if (!githubConfigured()) {
      throw new AppError('GitHub OAuth is not configured', 503, ErrorCode.SERVICE_UNAVAILABLE);
    }

    const errorParam = String(req.query.error || '').trim();
    if (errorParam) {
      return res.redirect(buildFrontendCallbackUrl({
        error: errorParam,
        message: String(req.query.error_description || errorParam),
      }));
    }

    const code = String(req.query.code || '').trim();
    const state = String(req.query.state || '').trim();
    const storedState = String(req.cookies?.[GITHUB_STATE_COOKIE] || '').trim();
    res.clearCookie(GITHUB_STATE_COOKIE, oauthCookieOptions());

    if (!code || !state || !storedState || state !== storedState) {
      throw new AppError('GitHub OAuth state verification failed', 400, ErrorCode.AUTHENTICATION_FAILED);
    }

    const accessToken = await exchangeGitHubCode(code, githubCallbackUrlOverride() || undefined);
    const profile = await fetchGitHubProfile(accessToken);
    const user = await upsertUserFromGitHubProfile(profile);
    const token = jwt.sign(
      { userId: user.id, mode: 'local-auth' },
      getJwtSecret(),
      { expiresIn: '7d' },
    );

    logger.info('[GitHubOAuth] login successful', {
      email: profile.email,
      userId: user.id,
      username: user.username,
    });

    return res.redirect(buildFrontendCallbackUrl({
      token,
      email: profile.email,
    }));
  } catch (error) {
    const message = error instanceof AppError ? error.message : error instanceof Error ? error.message : 'GitHub OAuth callback failed';
    logger.error('[GitHubOAuth] callback failed', { error: message });
    return res.redirect(buildFrontendCallbackUrl({
      error: 'oauth_callback_failed',
      message,
    }));
  }
};

