export const rejectPromoClaim = async (req: AuthRequest, res: Response, next: NextFunction) => { try { if (!isAdmin(req)) throw new AppError('Forbidden', 403, ErrorCode.FORBIDDEN); const claimId = Number(req.params.id); if (!Number.isInteger(claimId)) throw new AppError('Invalid claim ID', 400, ErrorCode.VALIDATION_ERROR); const updated = await prisma.promoClaimRecord.update({ where: { id: claimId }, data: { claim_status: 'REJECTED', reward_status: 'PENDING', audit_by: req.user?.id ?? null, audit_note: req.body?.remark || 'Rejected', failed_reason: req.body?.remark || 'Rejected by admin' } }); return sendSuccess(res, updated, 'Claim rejected'); } catch (error) { next(error); } };

export const getPromoAuditSummary = async (_req: AuthRequest, res: Response, next: NextFunction) => { try { const [tasks, claims, bindings] = await Promise.all([prisma.promoTask.count(), prisma.promoClaimRecord.count(), prisma.promoPlatformBinding.count()]); const rewarded = await prisma.promoClaimRecord.count({ where: { reward_status: 'REWARDED' } }); const pending = await prisma.promoClaimRecord.count({ where: { claim_status: 'PENDING' } }); const rejected = await prisma.promoClaimRecord.count({ where: { claim_status: 'REJECTED' } }); return sendSuccess(res, { tasks, claims, bindings, rewarded, pending, rejected }, 'Promo summary loaded'); } catch (error) { next(error); } };

import { Request, Response, NextFunction } from 'express';



import Session from 'supertokens-node/recipe/session';
import RecipeUserId from 'supertokens-node/lib/build/recipeUserId';
import jwt from 'jsonwebtoken';
import crypto from 'crypto';



import prisma from '../db';



import { sendSuccess, toSafeUser } from '../utils/response';



import bcrypt from 'bcrypt';



import { AppError, ErrorCode } from '../utils/errors';



import { logger } from '../utils/logger';



import { getOrCreateSuperTokensUser } from '../services/superTokensUser';
import { sendEmailLoginCode } from '../services/emailService';
import { getJwtSecret } from '../utils/securityConfig';







interface RegisteredUser {



  id: number;



  email?: string;



  phone?: string;



  username: string;



  display_name?: string;



  role: string;



  created_at: Date;



}







function normalizeEmail(email: string) {



  return email.trim().toLowerCase();



}







function normalizePhone(phone: string) {



  return phone.trim().replace(/[\s-]/g, '');



}

function generateCode() {
  return String(Math.floor(100000 + Math.random() * 900000));
}







function generateCodeHash(identifier: string, code: string): string {

  const secret = getJwtSecret();



  return crypto.createHmac('sha256', secret).update(`${identifier}:${code}`).digest('hex');



}



/**

 * 注册用户

 * 流程：验证验证码 → 创建用户 → 创建 SuperTokens 用户 → 创建会话 → 返回 token

 * 支持 email 和 phone 双通道注册

 *

 * 关键修复：注册成功后立即清除 Prisma 中的 verification_token，

 * 防止验证码被复用攻击。

 */

export const registerUser = async (req: Request, res: Response, next: NextFunction) => {

  try {

    const { email, phone, code, username, password } = req.body;

    const emailStr = typeof email === 'string' ? email.trim() : '';

    const phoneStr = typeof phone === 'string' ? phone.trim() : '';



    if (!username || !password) {

      throw new AppError(

        'username and password are required (email or phone is required)',

        400,

        ErrorCode.VALIDATION_ERROR,

      );

    }



    if (!emailStr && !phoneStr) {

      throw new AppError('Email or phone is required', 400, ErrorCode.VALIDATION_ERROR);

    }

    if (!emailStr) {

      throw new AppError('Phone-only registration is not supported by the current user schema', 400, ErrorCode.VALIDATION_ERROR);

    }



    const usernameNorm = username.trim();

    const passwordStr = password;



    if (usernameNorm.length < 3 || usernameNorm.length > 30) {

      throw new AppError('Username must be 3-30 characters', 400, ErrorCode.VALIDATION_ERROR);

    }



    if (!/^[a-zA-Z0-9_-]+$/.test(usernameNorm)) {

      throw new AppError(

        'Username can only contain letters, numbers, underscores and hyphens',

        400,

        ErrorCode.VALIDATION_ERROR,

      );

    }



    const passwordFinal: string = passwordStr;

    if (passwordFinal.length < 8) {

      throw new AppError('Password must be at least 8 characters', 400, ErrorCode.VALIDATION_ERROR);

    }



    // 确定注册渠道类型

    const type = emailStr ? 'email' : 'phone';

    const identifier = emailStr ? normalizeEmail(emailStr) : normalizePhone(phoneStr);



    // 渠道特定验证

    if (type === 'email' && emailStr.length < 5) {

      throw new AppError('Email format is invalid', 400, ErrorCode.VALIDATION_ERROR);

    }



    // 检查用户名是否已存在

    const existingUser = await prisma.user.findFirst({

      where: { username: usernameNorm },

    });



    if (existingUser) {

      throw new AppError('Username is already taken', 409, ErrorCode.CONFLICT);

    }



    // 检查 email 是否已被注册（如果提供了 email）

    if (type === 'email') {

      const emailExists = await prisma.user.findUnique({ where: { email: identifier } });

      if (emailExists) {

        throw new AppError('Email is already registered', 409, ErrorCode.CONFLICT);

      }

    }



    // 检查 phone 是否已被注册（如果提供了 phone）

    if (type === 'phone') {

      const phoneExists = await prisma.user.findUnique({ where: { phone: identifier } });

      if (phoneExists) {

        throw new AppError('Phone is already registered', 409, ErrorCode.CONFLICT);

      }

    }



    const user = await prisma.user.findFirst({

      where: {

        OR: [

          type === 'email' ? { email: identifier } : {},

          type === 'phone' ? { phone: identifier } : {},

        ].filter(Boolean),

      },

    });



    if (!user) {

      // 新用户注册：先创建未验证账号，并立即发出邮箱验证码。

      let stUserId: string | null = null;

      try {

        stUserId = emailStr ? await getOrCreateSuperTokensUser(emailStr) : null;

      } catch (stError) {

        logger.warn('[Register] SuperTokens user creation failed, continuing without ST user:', stError);

      }



      const passwordHash = await bcrypt.hash(passwordFinal, 12);
      const verificationCode = generateCode();
      const verificationToken = generateCodeHash(identifier, verificationCode);
      const tokenExpiry = new Date(Date.now() + 10 * 60 * 1000);

      const newUser = await prisma.user.create({

        data: {

          email: identifier,

          username: usernameNorm,

          display_name: usernameNorm,

          password_hash: passwordHash,

          supertokens_user_id: stUserId || undefined,

          email_verified: false,

          verification_token: verificationToken,

          token_expiry: tokenExpiry,

          last_code_send_at: new Date(),

        },

      });

      await sendEmailLoginCode(identifier, verificationCode);



      let accessToken: string | null = null;

      let refreshToken: string | null = null;

      if (stUserId) {

        try {

          const session = await Session.createNewSession(req, res, process.env.NEXT_PUBLIC_SUPER_TOKENS_TENANT_ID || '1', new RecipeUserId(stUserId));

          accessToken = session.getAccessToken();

          const tokens = session.getAllSessionTokensDangerously();

          refreshToken = tokens.refreshToken || null;

        } catch (stError) {

          logger.warn('[Register] Failed to create SuperTokens session:', stError);

        }

      }



      const token = jwt.sign(
        { userId: newUser.id, mode: 'local-auth' },
        getJwtSecret(),
        { expiresIn: '7d' },
      );

      return sendSuccess(res, {

        user: toSafeUser(newUser, { mask: false }),

        token,

        accessToken,

        refreshToken,

      }, 'Registration successful', 200, undefined, { mask: false });

    }



    // 已存在用户：验证验证码，如果正确则登录

    const codeStr = typeof code === 'string' ? code.trim() : '';
    if (!codeStr) {
      throw new AppError('Verification code is required for existing accounts', 400, ErrorCode.VALIDATION_ERROR);
    }
    const verificationToken = generateCodeHash(identifier, codeStr);



    if (

      !user.verification_token ||

      !user.token_expiry ||

      user.token_expiry < new Date() ||

      user.verification_token !== verificationToken

    ) {

      throw new AppError('Invalid or expired verification code', 400, ErrorCode.BAD_REQUEST);

    }



    // 注册成功：清除验证码，防止复用

    await prisma.user.update({

      where: { id: user.id },

      data: {

        username: usernameNorm,

        display_name: usernameNorm,

        ...(type === 'email' ? { email: identifier } : { phone: identifier }),

        password_hash: await bcrypt.hash(passwordFinal, 12),

        email_verified: true,

        verification_token: null,

        token_expiry: null,

      },

    });



    // 登录：创建 SuperTokens 会话

    let stUserId = user.supertokens_user_id;

    if (!stUserId) {

      stUserId = user.email ? await getOrCreateSuperTokensUser(user.email) : null;

      if (stUserId) {

        await prisma.user.update({

          where: { id: user.id },

          data: { supertokens_user_id: stUserId },

        });

      }

    }



    let accessToken: string | null = null;

    let refreshToken: string | null = null;

    if (stUserId) {

      try {

        const session = await Session.createNewSession(req, res, process.env.NEXT_PUBLIC_SUPER_TOKENS_TENANT_ID || '1', new RecipeUserId(stUserId), {}, {});

        accessToken = session.getAccessToken();

        const tokens = session.getAllSessionTokensDangerously();

        refreshToken = tokens.refreshToken || null;

      } catch (stError) {

        logger.warn('[Register] Failed to create SuperTokens session:', stError);

      }

    }



    return sendSuccess(res, {

      user: {

        id: user.id,

        email: user.email || undefined,

        phone: user.phone || undefined,

        username: user.username,

        display_name: user.display_name,

        role: user.role,

        created_at: user.created_at,

      },

      accessToken,

      refreshToken,

    }, 'Code verified and logged in');

  } catch (error) {

    logger.error('[Register] Registration failed:', error);

    next(error);

  }

};

import { Response, NextFunction } from 'express';
import prisma from '../db';
import localPrisma from '../localDb';
import { logger } from '../utils/logger';
import { REVIEW_CONFIG, ReviewStatus } from '../config/reviewConfig';
import { AuthRequest } from '../middleware/auth';
import { AppError, ErrorCode } from '../utils/errors';
import { logAction, logDataChange } from '../services/auditService';
import { syncServerToMainDB } from '../services/syncService';
import { redisService } from '../services/redisService';

import { withCache } from '../services/cache';

const REVIEW_STATS_CACHE_KEY = 'admin:review_stats';

import { reviewActionSchema, batchReviewSchema, reviewQuerySchema, serverIdParamSchema, paginationQuerySchema } from '../utils/validation';
import { sanitize } from '../services/sanitize';
import { hookService, MotiaHook } from '../services/hookService';

import { clearPublicServersCache } from '../services/publicServerCache';
import { parseJsonArray } from '../utils/jsonField';
import {
  sendBatchResponse,
  sendDetailResponse,
  sendListResponse,
  sendUpdatedResponse,
} from '../utils/response';

export const getPendingReviews = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    if (!req.user) {
      throw new AppError('Unauthorized', 401, ErrorCode.UNAUTHORIZED);
    }

    const validation = reviewQuerySchema.safeParse(req.query);
    if (!validation.success) {
      throw new AppError('Invalid query parameters', 400, ErrorCode.VALIDATION_ERROR, false, {
        issues: validation.error.issues,
      });
    }
    const { sortBy, sortOrder, page, limit } = validation.data;
    const skip = (page - 1) * limit;

    const pendingServers = await localPrisma.server.findMany({
      where: {
        review_status: 'PENDING'
      },
      skip,
      take: limit,
      orderBy: {
        [sortBy]: sortOrder
      },
      include: {
        owner: {
          select: {
            id: true,
            username: true,
            email: true,
            role: true
          }
        }
      }
    });

    const totalCount = await localPrisma.server.count({
      where: {
        review_status: 'PENDING'
      }
    });

    return sendListResponse(res, pendingServers, totalCount, page, limit, { resource: 'Review task' });

  } catch (error) {
    next(error);
  }
};

/**
 * Review a server submission
 */
export const reviewServer = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    if (!req.user || !req.user.id) {
      throw new AppError('Unauthorized', 401, ErrorCode.UNAUTHORIZED);
    }

    const idValidation = serverIdParamSchema.safeParse(req.params);
    if (!idValidation.success) {
      throw new AppError('Invalid server ID', 400, ErrorCode.VALIDATION_ERROR, false, {
        issues: idValidation.error.issues,
      });
    }
    const { serverId: serverIdInt } = idValidation.data;

    const validation = reviewActionSchema.safeParse(req.body);
    if (!validation.success) {
      throw new AppError('Invalid input', 400, ErrorCode.VALIDATION_ERROR, false, {
        issues: validation.error.issues,
      });
    }

    const { status, notes: feedback, score } = validation.data;
    const sanitizedFeedback = feedback ? sanitize(feedback) : '';

    if (!Object.values(ReviewStatus).includes(status as any)) {
      throw new AppError('Invalid status', 400, ErrorCode.INVALID_INPUT);
    }

    const server = await localPrisma.server.findUnique({
      where: { id: serverIdInt }
    });

    if (!server) {
      throw new AppError('Server not found', 404, ErrorCode.NOT_FOUND);
    }

    if (server.owner_id === req.user.id && (req.user as any).role !== 'ADMIN') {
      throw new AppError('Cannot review your own server', 403, ErrorCode.FORBIDDEN);
    }

    const updatedServer = await localPrisma.$transaction(async (tx: any) => {
      const currentServer = await tx.server.findUnique({
        where: { id: serverIdInt }
      });

      if (!currentServer || currentServer.review_status !== 'PENDING') {
        throw new AppError('Server not found or already reviewed', 400, ErrorCode.INVALID_OPERATION);
      }

      const updated = await tx.server.update({
        where: { id: serverIdInt },
        data: {
          review_status: status,
          review_notes: sanitizedFeedback,
          reviewed_by: req.user!.id,
          reviewed_at: new Date()
        }
      });

      return updated;
    });

    syncServerToMainDB(updatedServer.id).catch(() => {});

    // Clear public cache since review status changed
    await clearPublicServersCache();
    await redisService.del(`server:info:${updatedServer.id}`);

    await prisma.reviewHistory.create({
      data: {
        server_id: serverIdInt,
        reviewer_id: req.user.id,
        action: status,
        notes: sanitizedFeedback + (score ? ` (Score: ${score})` : ''),
        created_at: new Date()
      }
    });

    await logDataChange(req.user.id, 'SERVER_REVIEWED', `server_${serverIdInt}`, req, server, updatedServer);

    // Trigger Hooks
    if (status === 'APPROVED') {
      hookService.trigger(MotiaHook.SERVER_APPROVED, { server: updatedServer, reviewer: req.user });
    } else if (status === 'REJECTED') {
      hookService.trigger(MotiaHook.SERVER_REJECTED, { server: updatedServer, reviewer: req.user, reason: sanitizedFeedback });
    }

    // Send notification to owner
    try {
      const locale = (req as any).locale || 'zh';
      const notificationTitle = status === 'APPROVED' 
        ? (locale === 'zh' ? '服务器审核通过' : 'Server Review Approved')
        : (locale === 'zh' ? '服务器审核未通过' : 'Server Review Rejected');

      const notificationContent = status === 'APPROVED'
        ? (locale === 'zh' ? `您的服务器 "${server.name}" 已通过审核并发布。` : `Your server "${server.name}" has been approved and published.`)
        : (locale === 'zh' ? `您的服务器 "${server.name}" 未通过审核。原因: ${sanitizedFeedback || '无'}` : `Your server "${server.name}" was not approved. Reason: ${sanitizedFeedback || 'None'}`);

      await localPrisma.notification.create({
        data: {
          user_id: server.owner_id,
          title: notificationTitle,
          content: notificationContent,
          type: status === 'APPROVED' ? 'SUCCESS' : 'ERROR'
        }
      });
    } catch (e) {
      logger.error('[Notification] Failed to send review notification:', {
        error: e instanceof Error ? e.message : String(e),
      });
    }

    return sendUpdatedResponse(res, updatedServer, { resource: 'Review' });

  } catch (error) {
    next(error);
  }
};

/**
 * Retrieve review history for a server
 */
export const getReviewHistory = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    if (!req.user) {
      throw new AppError('Unauthorized', 401, ErrorCode.UNAUTHORIZED);
    }

    const idValidation = serverIdParamSchema.safeParse(req.params);
    if (!idValidation.success) {
      throw new AppError('Invalid server ID', 400, ErrorCode.VALIDATION_ERROR, false, {
        issues: idValidation.error.issues,
      });
    }
    const { serverId: serverIdInt } = idValidation.data;

    const queryValidation = paginationQuerySchema.safeParse(req.query);
    if (!queryValidation.success) {
      throw new AppError('Invalid query parameters', 400, ErrorCode.VALIDATION_ERROR, false, {
        issues: queryValidation.error.issues,
      });
    }
    const { page, limit } = queryValidation.data;
    const skip = (page - 1) * limit;

    // Security Check: Verify ownership or admin/reviewer status
    const server = await localPrisma.server.findUnique({
      where: { id: serverIdInt },
      select: { owner_id: true }
    });

    if (!server) {
      throw new AppError('Server not found', 404, ErrorCode.NOT_FOUND);
    }

    if (server.owner_id !== req.user.id && !req.isAdmin) {
      throw new AppError('Forbidden: You do not have permission to view this server\'s review history', 403, ErrorCode.FORBIDDEN);
    }

    const history = await prisma.reviewHistory.findMany({
      where: {
        server_id: serverIdInt
      },
      include: {
        reviewer: {
          select: {
            username: true,
            display_name: true
          }
        }
      },
      skip,
      take: limit,
      orderBy: {
        created_at: 'desc'
      }
    });

    const totalCount = await prisma.reviewHistory.count({
      where: {
        server_id: serverIdInt
      }
    });

    return sendListResponse(res, history, totalCount, page, limit, { resource: 'Review history' });

  } catch (error) {
    next(error);
  }
};

/**
 * Batch review multiple servers
 */
export const batchReview = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    if (!req.user) {
      throw new AppError('Unauthorized', 401, ErrorCode.UNAUTHORIZED);
    }

    const validation = batchReviewSchema.safeParse(req.body);
    if (!validation.success) {
      throw new AppError('Invalid input', 400, ErrorCode.VALIDATION_ERROR, false, validation.error.issues);
    }

    const { serverIds, status, feedback } = validation.data;
    const sanitizedFeedback = feedback ? sanitize(feedback) : '';

    const results = await Promise.allSettled(
      serverIds.map(async (serverId: number) => {
        try {
          const result = await localPrisma.$transaction(async (tx: any) => {
            const server = await tx.server.findUnique({
              where: { id: serverId }
            });

            if (!server || server.review_status !== 'PENDING') {
              return { serverId, success: false, error: 'Not pending' };
            }

            const updatedServer = await tx.server.update({
              where: { id: serverId },
              data: {
                review_status: status,
                review_notes: sanitizedFeedback,
                reviewed_by: req.user!.id,
                reviewed_at: new Date()
              }
            });

            // Send notification
            try {
              const locale = (req as any).locale || 'zh';
              const notificationTitle = status === 'APPROVED' 
                ? (locale === 'zh' ? '服务器批量审核通过' : 'Server Batch Review Approved')
                : (locale === 'zh' ? '服务器批量审核未通过' : 'Server Batch Review Rejected');

              const notificationContent = status === 'APPROVED' 
                ? (locale === 'zh' ? `您的服务器 "${server.name}" 已通过批量审核并发布。` : `Your server "${server.name}" has been approved and published via batch review.`)
                : (locale === 'zh' ? `您的服务器 "${server.name}" 未通过批量审核。原因: ${sanitizedFeedback || '无'}` : `Your server "${server.name}" was not approved via batch review. Reason: ${sanitizedFeedback || 'None'}`);

              await tx.notification.create({
                data: {
                  user_id: server.owner_id,
                  title: notificationTitle,
                  content: notificationContent,
                  type: status === 'APPROVED' ? 'SUCCESS' : 'ERROR'
                }
              });
            } catch (e) {}

            await logDataChange(req.user!.id, 'SERVER_BATCH_REVIEWED', `server_${serverId}`, req, server, updatedServer);

            // Trigger Hooks
            if (status === 'APPROVED') {
              hookService.trigger(MotiaHook.SERVER_APPROVED, { server: updatedServer, reviewer: req.user, batch: true });
            } else if (status === 'REJECTED') {
              hookService.trigger(MotiaHook.SERVER_REJECTED, { server: updatedServer, reviewer: req.user, reason: sanitizedFeedback, batch: true });
            }

            return { serverId, success: true, serverName: server.name, updatedServerId: updatedServer.id };
          });

          if (result.success && result.updatedServerId) {
            syncServerToMainDB(result.updatedServerId).catch(err => {
              logger.error(`[Sync] Batch sync failed for server ${result.updatedServerId}: ${err.message}`);
            });

            await prisma.reviewHistory.create({
              data: {
                server_id: serverId,
                reviewer_id: req.user!.id,
                action: status,
                notes: sanitizedFeedback,
                created_at: new Date()
              }
            });
          }

          return result;
        } catch (err: any) {
          return { serverId, success: false, error: err.message };
        }
      })
    );

    const successful = results.filter(r => r.status === 'fulfilled' && r.value.success).length;
    const failed = results.filter(r => r.status === 'fulfilled' && !r.value.success).length;

    // Clear caches if any successful reviews
    if (successful > 0) {
      await clearPublicServersCache();

      // Clear individual server caches
      for (const res of results) {
        if (res.status === 'fulfilled' && res.value.success) {
          const val = res.value as any;
          if (val.updatedServerId) {
            await redisService.del(`server:info:${val.updatedServerId}`);
          }
        }
      }
    }

    await logAction(req.user.id, 'BATCH_REVIEW_COMPLETED', 'review', req, {
      total: serverIds.length,
      successful,
      failed,
      status
    });

    return sendBatchResponse(
      res,
      results.map((result) => {
        if (result.status === 'fulfilled') {
          return {
            id: result.value.serverId,
            success: result.value.success,
            data: result.value.success
              ? {
                  updatedServerId: (result.value as { updatedServerId?: number }).updatedServerId,
                  serverName: (result.value as { serverName?: string }).serverName,
                }
              : undefined,
            error: result.value.success ? undefined : result.value.error,
          };
        }

        return {
          success: false,
          error: result.reason instanceof Error ? result.reason.message : String(result.reason),
        };
      }),
      {
        resource: 'Review',
        meta: {
          total: serverIds.length,
          successful,
          failed,
          status,
        },
      },
    );

  } catch (error) {
    next(error);
  }
};

/**
 * Get review system statistics
 */
export const getReviewStats = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    if (!req.user) {
      throw new AppError('Unauthorized', 401, ErrorCode.UNAUTHORIZED);
    }

    const stats = await withCache(REVIEW_STATS_CACHE_KEY, async () => {
      const totalPending = await localPrisma.server.count({
        where: { review_status: 'PENDING' }
      });

      const totalApproved = await localPrisma.server.count({
        where: { review_status: 'APPROVED' }
      });

      const totalRejected = await localPrisma.server.count({
        where: { review_status: 'REJECTED' }
      });

      const today = new Date();
      today.setHours(0, 0, 0, 0);

      const totalTodayReviews = await prisma.reviewHistory.count({
        where: {
          created_at: {
            gte: today
          }
        }
      });

      return {
        totalPending,
        totalApproved,
        totalRejected,
        totalTodayReviews
      };
    }, { ttl: 300000 }); // 5 minutes cache

    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const userReviewsToday = await prisma.reviewHistory.count({
      where: {
        reviewer_id: req.user.id,
        created_at: {
          gte: today
        }
      }
    });

    await logAction(req.user.id, 'REVIEW_STATS_VIEWED', 'review', req, {
      ...stats,
      userReviewsToday
    });

    return sendDetailResponse(res, {
      ...stats,
      userReviewsToday,
      reviewLimits: REVIEW_CONFIG.PERMISSIONS.REVIEW_LIMITS
    }, { resource: 'Review stats' });

  } catch (error) {
    next(error);
  }
};

import { Request, Response, NextFunction } from 'express';
import localPrisma from '../localDb';
