  idParamSchema,
  serverCommentBodySchema,
  playerHistoryQuerySchema,
  paginationQuerySchema,
} from '../utils/validation';
import {
  listServerStatusHistory,
  aggregateHistoryPoints,
} from '../services/serverStatusHistoryService';
